# ---------- the Grade 2 book (her 14 Nov "계속 가줘"): same storybook format; new keys D major, B minor, B flat major, G minor (natural, harmonic, melodic), as in data_technical_ameb.js ----------
def ksig2(sh=(), fl=(), w=230):   # a treble staff with sharps / flats at staff steps (8 = top line F, 5 = C space, 4 = B line, 7 = E space)
    o = st([], 't', w, names=False); body = o[:o.rindex('</svg>')]; y = lambda k: 46 + 4 * 24 - k * 12
    for j, k in enumerate(sh): body += f'<text x="{108 + j * 26}" y="{y(k) + 15}" font-size="54" font-weight="700" fill="{C}" {F_} text-anchor="middle">♯</text>'
    for j, k in enumerate(fl): body += f'<text x="{108 + j * 26}" y="{y(k) + 12}" font-size="58" font-weight="700" fill="{C}" {F_} text-anchor="middle">♭</text>'
    return body + '</svg>'
def capd(t): return f'<div style="text-align:center;font-size:19px;font-weight:700;color:{N};margin:4px 0 12px">{t}</div>'
def kb2(a, ca, b_, cb): return f'<div>{a}{capd(ca)}{b_}{capd(cb)}</div>'
def trip(h=150):   # three quavers beamed with a 3 over the beam
    s = bq(3, h); return s.replace('viewBox="0 0 ', 'viewBox="0 -44 ', 1).replace(f'height:{h}px', f'height:{h * 180 / 136:.0f}px', 1).replace('136"', '180"', 1).replace('</svg>', f'<text x="109" y="-10" text-anchor="middle" font-size="40" font-weight="700" fill="{C}" {F_}>3</text></svg>')
def upbeat():
    c = lambda lab, red: f'<span style="display:inline-flex;flex-direction:column;align-items:center;gap:8px;width:58px"><span style="width:{44 if red else 30}px;height:{44 if red else 30}px;border-radius:50%;background:{C if red else N}"></span><b style="font-size:21px;color:{C if red else N}">{lab}</b></span>'
    bar = f'<span style="width:4px;height:74px;background:{N};margin:0 12px;align-self:flex-start"></span>'
    return f'<div style="display:flex;align-items:flex-start;justify-content:center"><span style="display:flex;flex-direction:column;align-items:center;gap:10px">{c("4", False)}<b style="font-size:17px;color:#6d6f9c">upbeat</b></span>{bar}' + ''.join(c(str(q), q == 1) for q in (1, 2, 3, 4)) + bar + ''.join(c(str(q), q == 1) for q in (1, 2, 3)) + f'<span style="width:4px;height:74px;background:{N};margin:0 3px 0 12px;align-self:flex-start"></span><span style="width:9px;height:74px;background:{N};align-self:flex-start"></span></div>'
def fermata():
    return f'<svg viewBox="0 0 300 260" style="width:300px"><path d="M70 92 A80 80 0 0 1 230 92" fill="none" stroke="{C}" stroke-width="12" stroke-linecap="round"/><circle cx="150" cy="78" r="12" fill="{C}"/><text x="150" y="250" text-anchor="middle" font-family="NM" font-size="150" fill="{N}">{MI}</text></svg>'
def pedals():
    p = lambda x, lab, sub, red: f'<rect x="{x - 34}" y="70" width="68" height="22" rx="11" fill="{C if red else "#fff"}" stroke="{N}" stroke-width="3"/><rect x="{x - 6}" y="20" width="12" height="52" fill="{N}"/><text x="{x}" y="132" text-anchor="middle" font-size="22" font-weight="700" fill="{C if red else N}" {F_}>{lab}</text><text x="{x}" y="158" text-anchor="middle" font-size="16" fill="#6d6f9c" {F_}>{sub}</text>'
    return f'<svg viewBox="0 0 640 170" style="width:600px"><rect x="20" y="4" width="600" height="16" fill="{N}"/>{p(110, "left", "softer", False)}{p(320, "middle", "not on every piano", False)}{p(530, "right", "keeps it ringing", True)}</svg>'
def pedmark():   # three minims, the pedal pressed just after the first, changed under the second and third, lifted at the end
    xs = (80, 250, 420); lab = ('C', 'E', 'G'); o = ''.join(f'<text x="{x}" y="130" font-family="NM" font-size="120" fill="{N}">{MI}</text><text x="{x + 22}" y="160" text-anchor="middle" font-size="20" font-weight="700" fill="{N}" {F_}>{l}</text>' for x, l in zip(xs, lab))
    return f'<svg viewBox="0 0 560 240" style="width:540px">{o}<path d="M112 176 L112 206 L262 206 L282 184 L302 206 L432 206 L452 184 L472 206 L540 206 L540 176" fill="none" stroke="{C}" stroke-width="5" stroke-linejoin="round"/><text x="112" y="234" text-anchor="middle" font-size="17" fill="#6d6f9c" {F_}>down</text><text x="282" y="234" text-anchor="middle" font-size="17" fill="#6d6f9c" {F_}>change</text><text x="452" y="234" text-anchor="middle" font-size="17" fill="#6d6f9c" {F_}>change</text><text x="540" y="234" text-anchor="middle" font-size="17" fill="#6d6f9c" {F_}>up</text></svg>'
def phrases():
    bx = ''.join(f'<rect x="{20 + i * 64}" y="70" width="64" height="60" fill="#fff" stroke="{N}" stroke-width="3"/><text x="{52 + i * 64}" y="108" text-anchor="middle" font-size="15" fill="#6d6f9c" {F_}>bar {i % 4 + 1}</text>' for i in range(8))
    arc = lambda x0, x1, lab: f'<path d="M{x0} 60 Q{(x0 + x1) / 2} 0 {x1} 60" fill="none" stroke="{C}" stroke-width="5" stroke-linecap="round"/><text x="{(x0 + x1) / 2}" y="160" text-anchor="middle" font-size="22" font-weight="700" fill="{C}" {F_}>{lab}</text>'
    return f'<svg viewBox="0 0 552 170" style="width:552px">{bx}{arc(26, 270, "question")}{arc(282, 526, "answer")}</svg>'
